def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        # Remove build metadata (everything after +)
        version = version.split('+')[0]

        # Split into core version and pre-release
        if '-' in version:
            core, prerelease = version.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = version
            prerelease_parts = None

        # Parse core version (MAJOR.MINOR.PATCH)
        core_parts = core.split('.')
        major, minor, patch = int(core_parts[0]), int(core_parts[1]), int(core_parts[2])

        return (major, minor, patch), prerelease_parts

    def compare_prerelease(pre_a, pre_b):
        # If both have no pre-release, they're equal in this regard
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            # If one has fewer identifiers, it has lower precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            # Numeric identifiers have lower precedence than non-numeric
            if is_numeric_a and not is_numeric_b:
                return -1
            if is_numeric_b and not is_numeric_a:
                return 1

            # Both numeric: compare numerically
            if is_numeric_a and is_numeric_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                if num_a > num_b:
                    return 1
            else:
                # Both non-numeric: compare lexically (ASCII order)
                if id_a < id_b:
                    return -1
                if id_a > id_b:
                    return 1

        return 0

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # Compare core versions
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # Core versions are equal, compare pre-release
    return compare_prerelease(pre_a, pre_b)
